  margin: 4px auto;
  background: var(--ink);
}

.hero {
  padding: 72px 0 54px;
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.03fr) minmax(320px, 0.97fr);
  gap: 54px;
  align-items: center;
}

.eyebrow {
  margin: 0 0 12px;
  color: var(--accent-dark);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  max-width: 720px;
  margin-bottom: 22px;
  font-size: clamp(3.2rem, 8vw, 6.85rem);
  line-height: 0.9;
  letter-spacing: -0.08em;
}

h2 {
  margin-bottom: 0;
  font-size: clamp(2rem, 4vw, 3.5rem);
  line-height: 1;
  letter-spacing: -0.06em;
}

h3 {
  margin-bottom: 12px;
  font-size: 1.45rem;
  line-height: 1.15;
  letter-spacing: -0.04em;
}

.hero-text {
  max-width: 620px;
  color: var(--muted);
  font-size: 1.15rem;
  line-height: 1.8;
}

.hero-actions,
.hero-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.hero-actions {
  margin-top: 30px;
}

.hero-stats {
  margin-top: 44px;
}

.hero-stats div {
  min-width: 132px;
  padding: 16px 18px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.52);
}

.hero-stats strong,
.hero-stats span {
  display: block;
}

.hero-stats strong {
  font-size: 1.5rem;
  letter-spacing: -0.05em;
}

.hero-stats span {
  color: var(--muted);
  font-size: 0.84rem;
}

.hero-showcase {
  position: relative;
  min-height: 610px;
}

.showcase-card {
  overflow: hidden;
  border-radius: 38px;
  background: var(--surface-strong);
  box-shadow: var(--shadow);
}

.showcase-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.card-large {
  position: absolute;
  inset: 0 0 78px 30px;
}

.card-large::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0, 0, 0, 0) 48%, rgba(0, 0, 0, 0.22));
}

.pill {
  position: absolute;
  top: 22px;
  left: 22px;
  z-index: 1;
  border-radius: 999px;
  padding: 10px 14px;
  background: rgba(255, 255, 255, 0.84);
  font-size: 0.8rem;
  font-weight: 800;
}

.card-small {
  position: absolute;
  left: 0;
  bottom: 0;
  width: min(300px, 72%);
  display: grid;
  grid-template-columns: 108px 1fr;
  gap: 16px;
  align-items: center;
  padding: 12px;
}

.card-small img {
  height: 108px;
  border-radius: 28px;
}

.card-small strong,
.card-small span {
  display: block;
}

.card-small span {
  margin-top: 6px;
  color: var(--muted);
}

.category-strip {
  padding: 18px 0;
}

.category-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
}

.category-grid a {
  display: grid;
  min-height: 72px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.54);
  font-weight: 800;
}

.section {
  padding: 82px 0;
}

.section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 28px;
  margin-bottom: 34px;
}

.text-link {
  color: var(--accent-dark);
  font-weight: 800;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
}

.product-card {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 30px;
  background: rgba(255, 255, 255, 0.72);
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.product-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow);
}

.product-media {
  position: relative;
  aspect-ratio: 1 / 1.1;
  overflow: hidden;
  background: var(--sage);
}

.product-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 260ms ease;
}

.product-card:hover .product-media img {
  transform: scale(1.05);
}

.product-badge {
  position: absolute;
  top: 14px;
  left: 14px;
  border-radius: 999px;
  padding: 8px 11px;
  background: rgba(255, 250, 243, 0.9);
  font-size: 0.75rem;
  font-weight: 800;
}

.product-info {
  padding: 18px;
}

.product-info p {
  margin-bottom: 14px;
  color: var(--muted);
}

.product-meta {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  font-weight: 800;
}

.deals-section {
  background: var(--charcoal);
  color: var(--surface);
}

.deals-section .eyebrow,
.deals-section .text-link {
  color: #f2b69b;
}

.deals-grid {
  display: grid;
  grid-template-columns: minmax(280px, 0.82fr) minmax(0, 1.18fr);
  gap: 24px;
}

.deal-spotlight,
.deal-card {
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 34px;
  background: rgba(255, 255, 255, 0.06);
}

.deal-spotlight {
  padding: clamp(28px, 5vw, 50px);
}

.deal-spotlight p:not(.eyebrow) {
  color: rgba(255, 250, 243, 0.72);
  line-height: 1.8;
}

.deal-cards {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.deal-card {
  padding: 22px;
}

.deal-card strong {
  display: block;
  margin-bottom: 28px;
  color: #f2b69b;
  font-size: 2.35rem;
  letter-spacing: -0.08em;
}

.deal-card p {
  color: rgba(255, 250, 243, 0.68);
  line-height: 1.6;
}

.editorial-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(280px, 0.7fr);
  gap: 22px;
}

.editorial-feature,
.editorial-card {
  border: 1px solid var(--line);
  border-radius: 34px;
  background: rgba(255, 255, 255, 0.72);
}

.editorial-feature {
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 0.9fr;
}

.editorial-feature img {
  width: 100%;
  height: 100%;
  min-height: 420px;
  object-fit: cover;
}

.editorial-feature div {
  align-self: center;
  padding: 34px;
}

.editorial-feature p:not(.eyebrow),
.editorial-card p {
  color: var(--muted);
  line-height: 1.7;
}

.editorial-list {
  display: grid;
  gap: 16px;
}

.editorial-card {
  padding: 24px;
}

.editorial-card .meta {
  color: var(--accent-dark);
  font-size: 0.82rem;
  font-weight: 800;
}

.membership {
  padding: 36px 0 86px;
}

.membership-card {
  display: grid;
  grid-template-columns: 1fr minmax(300px, 0.82fr);
  gap: 24px;
  align-items: center;
  border-radius: 38px;
  padding: clamp(28px, 5vw, 54px);
  background: linear-gradient(135deg, #e4d7c3, #f8f1e8 46%, #c8d4bd);
  box-shadow: var(--shadow);
}

.signup-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
}

.signup-form input {
  width: 100%;
  min-height: 52px;
  border: 1px solid rgba(24, 21, 18, 0.14);
  border-radius: 999px;
  padding: 0 18px;
  background: rgba(255, 255, 255, 0.76);
  color: var(--ink);
  font: inherit;
  outline: none;
}

.signup-form input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 4px rgba(197, 101, 63, 0.14);
}

.form-message {
  grid-column: 1 / -1;
  min-height: 20px;
  margin: 0;
  color: var(--accent-dark);
  font-size: 0.9rem;
  font-weight: 700;
}

.site-footer {
  border-top: 1px solid var(--line);
  padding: 36px 0;
  background: #fffaf3;
}

.footer-grid {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.footer-grid p {
  max-width: 430px;
  margin: 14px 0 0;
  color: var(--muted);
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  color: var(--muted);
  font-weight: 700;
}

@media (max-width: 920px) {
  .nav-action {
    display: none;
  }

  .nav-toggle {
    display: block;
  }

  .nav-menu {
    position: absolute;
    top: 76px;
    left: 20px;
    right: 20px;
    display: none;
    flex-direction: column;
    align-items: stretch;
    gap: 4px;
    border: 1px solid var(--line);
    border-radius: 24px;
    padding: 12px;
    background: rgba(255, 250, 243, 0.96);
    box-shadow: var(--shadow);
  }

  .nav-menu.is-open {
    display: flex;
  }

  .nav-menu a {
    padding: 14px;
    border-radius: 16px;
  }

  .nav-menu a:hover {
    background: rgba(197, 101, 63, 0.08);
  }

  .hero-grid,
  .deals-grid,
  .editorial-grid,
  .membership-card {
    grid-template-columns: 1fr;
  }

  .hero-showcase {
    min-height: 520px;
  }

  .product-grid,
  .category-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .editorial-feature {
    grid-template-columns: 1fr;
  }

  .editorial-feature img {
    min-height: 310px;
  }
}

@media (max-width: 620px) {
  .container {
    width: min(100% - 28px, 1140px);
  }

  .hero {
    padding-top: 48px;
  }

  h1 {
    font-size: clamp(3rem, 18vw, 4.6rem);
  }

  .section {
    padding: 60px 0;
  }

  .section-heading,
  .footer-grid {
    display: block;
  }

  .section-heading .text-link {
    display: inline-block;
    margin-top: 18px;
  }

  .hero-showcase {
    min-height: 420px;
  }

  .card-large {
    inset: 0 0 58px 0;
  }

  .product-grid,
  .deal-cards,
  .category-grid {
    grid-template-columns: 1fr;
  }

  .category-grid a {
    min-height: 58px;
  }

  .signup-form {
    grid-template-columns: 1fr;
  }

  .footer-links {
    margin-top: 22px;
  }
}
